#### **标准命令类结构**
```csharp
public class DrawHeroRewardCommand : CommandBase
{
    // 构造函数: 设置API路由和参数
    public DrawHeroRewardCommand(int show = 1) : base("lottery.hero.bonus")
    {
        putParam("show", show);
    }

    // 处理服务器响应
    public override bool handleRecieve(CCDictionary dict)
    {
        CCDictionary vparams = Global._dict(dict.objectForKey("params"));
        if (vparams == null) return false;

        string errorCode = vparams.valueForKey("errorCode");
        if (!string.IsNullOrEmpty(errorCode))
        {
            callFail(NetResult.CreateWithFail(vparams));
        }
        else
        {
            callSuccess(NetResult.Create(Error.Error_OK, vparams));
        }
        return true;
    }
}
```

